
if not getgenv().BondFarmSetting then 
  setclipboard[[
-- Paste this line on top of the script, you missed the settings 
-- set true/false to enable/disable feature in settings 
    getgenv().BondFarmSetting = {
        tweenDuration = 15, -- the lower number you set, the faster teleport speed you teleport ( don't make it lower than 13 or else it will skip every bonds in map because you teleport so fast to collect)
        AutoExecute = true, -- Turn this to true to make this script auto run when you joined new game without using auto executor from your executor, do not turn this to true if you already added the script into your executor auto executor file or else it will crash
        CheckMissedBonds = true -- turn this to true know how many bonds you missed (to know which tween duration is best)
    }
]]
end

